// Функция для проверки наличия слова "удалить" в первых строках тела письма
function isUnsubscribeMessage(bodyText) {
  if (!bodyText) return false;

  // Разбиваем тело письма на строки
  const lines = bodyText.split("\n");

  // Проверяем первые 5 строк (или меньше, если строк меньше)
  const linesToCheck = Math.min(5, lines.length);

  for (let i = 0; i < linesToCheck; i++) {
    const line = lines[i].trim().toLowerCase();

    // Пропускаем пустые строки
    if (line.length === 0) continue;

    // Проверяем, содержит ли строка слово "удалить"
    if (line.includes("удалить")) {
      // Удаляем все знаки препинания и лишние пробелы для проверки
      const cleanedLine = line
        .replace(/[^\w\s]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      const words = cleanedLine.split(" ");

      // Проверяем, что в строке только слово "удалить" (возможно с вариациями)
      // игнорируем пустые строки и знаки препинания
      const nonEmptyWords = words.filter((word) => word.length > 0);

      // Проверяем каждое слово - должно быть только "удалить" или его формы
      const hasOnlyUnsubscribeWord = nonEmptyWords.every(
        (word) =>
          word === "удалить" ||
          word === "удалит" ||
          word === "удали" ||
          word.startsWith("удалит"), // на случай если есть окончания
      );

      if (hasOnlyUnsubscribeWord) {
        return true;
      }
    }
  }

  return false;
}

