// Функция для проверки соответствия шаблону
function matchesPattern(text, pattern) {
  if (!pattern || !text) return false;

  // Проверяем условия для темы (должны содержаться)
  if (
    pattern.subject &&
    Array.isArray(pattern.subject) &&
    pattern.subject.length > 0
  ) {
    const subjectMatch = pattern.subject.some((keyword) =>
      subject.toLowerCase().includes(keyword.toLowerCase()),
    );
    if (!subjectMatch) return false;
  }

  // Проверяем условия для темы (НЕ должно быть НИ ОДНОГО слова из списка)
  if (
    pattern.subject_not_contains &&
    Array.isArray(pattern.subject_not_contains) &&
    pattern.subject_not_contains.length > 0
  ) {
    const hasForbiddenWord = pattern.subject_not_contains.some((keyword) =>
      subject.toLowerCase().includes(keyword.toLowerCase()),
    );
    // Если найдено хотя бы одно запрещенное слово - условие не выполняется
    if (hasForbiddenWord) return false;
  }

  // Проверяем условия для тела письма (должны содержаться)
  if (pattern.body && Array.isArray(pattern.body) && pattern.body.length > 0) {
    // Если тело - массив массивов (сложный шаблон с несколькими условиями)
    if (Array.isArray(pattern.body[0])) {
      const bodyMatch = pattern.body.every((conditionArray) =>
        conditionArray.some((keyword) =>
          body.toLowerCase().includes(keyword.toLowerCase()),
        ),
      );
      if (!bodyMatch) return false;
    } else {
      // Простой шаблон - достаточно одного совпадения
      const bodyMatch = pattern.body.some((keyword) =>
        body.toLowerCase().includes(keyword.toLowerCase()),
      );
      if (!bodyMatch) return false;
    }
  }

  // Проверяем условия для тела письма (НЕ должно быть НИ ОДНОГО слова из списка)
  if (
    pattern.body_not_contains &&
    Array.isArray(pattern.body_not_contains) &&
    pattern.body_not_contains.length > 0
  ) {
    const hasForbiddenWord = pattern.body_not_contains.some((keyword) =>
      body.toLowerCase().includes(keyword.toLowerCase()),
    );
    // Если найдено хотя бы одно запрещенное слово - условие не выполняется
    if (hasForbiddenWord) return false;
  }

  return true;
}

