      "http://37.18.2.51:8082/v1/get_mailing_history_id",
      params,
      { headers: { "Content-Type": "application/json" } }
    );

    return {
      success: true,
      data: response.data,
      params: params
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      params: params
    };
  }
}

